import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.vDgOMd_y.js";const m=JSON.parse('{"title":"Slash Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/slash-commands.md","filePath":"en/reference/slash-commands.md"}'),s={name:"en/reference/slash-commands.md"};function i(n,t,r,l,c,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/reference/slash-commands.md for this page in Markdown format</div><h1 id="slash-commands" tabindex="-1">Slash Commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash Commands&quot;">​</a></h1><p>Slash commands are built-in control commands provided by Kimi Code CLI in the interactive TUI, covering account configuration, session management, mode switching, information queries, and more. Type <code>/</code> in the input box to trigger command completion — the candidate list filters in real time as you continue typing; command aliases are also matched.</p><p>After typing the full command name, press <code>Enter</code> to execute. If the <code>/</code>-prefixed input does not match any built-in or Skill command, it is sent to the Agent as a regular message.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Some commands are only available in the idle state. Executing these commands while a session is streaming output or compacting context will be blocked — press <code>Esc</code> or <code>Ctrl-C</code> to interrupt first. The &quot;Always available&quot; column in the tables below indicates commands that are also available during streaming.</p></div><h2 id="account-configuration" tabindex="-1">Account &amp; Configuration <a class="header-anchor" href="#account-configuration" aria-label="Permalink to &quot;Account &amp; Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Description</th><th>Always available</th></tr></thead><tbody><tr><td><code>/login</code></td><td>—</td><td>Select an account or platform and log in: Kimi Code uses OAuth device-code flow; Kimi Platform uses API key login</td><td>No</td></tr><tr><td><code>/logout</code></td><td>—</td><td>Clear credentials for the currently selected account</td><td>No</td></tr><tr><td><code>/provider</code></td><td>—</td><td>Open the interactive provider manager to view, add, and remove configured providers. See <a href="./../configuration/providers.html#provider-—-interactive-provider-management">Platforms &amp; Models — <code>/provider</code> and provider management</a></td><td>Yes</td></tr><tr><td><code>/model</code></td><td>—</td><td>Switch the LLM model used in the current session</td><td>Yes</td></tr><tr><td><code>/secondary_model</code></td><td>—</td><td>Configure the secondary model that newly spawned subagents bind to by default (writes the <a href="./../configuration/config-files.html#secondary-model"><code>[secondary_model]</code></a> section and applies to the current session immediately). Requires the <code>secondary-model</code> experiment</td><td>Yes</td></tr><tr><td><code>/settings</code></td><td><code>/config</code></td><td>Open the settings panel inside the TUI</td><td>Yes</td></tr><tr><td><code>/experiments</code></td><td><code>/experimental</code></td><td>Open the experimental feature panel</td><td>Yes</td></tr><tr><td><code>/permission</code></td><td>—</td><td>Select a permission mode</td><td>Yes</td></tr><tr><td><code>/editor</code></td><td>—</td><td>Configure the external editor launched by <code>Ctrl-G</code></td><td>Yes</td></tr><tr><td><code>/theme</code></td><td>—</td><td>Switch the terminal UI color theme</td><td>Yes</td></tr></tbody></table><h2 id="session-management" tabindex="-1">Session Management <a class="header-anchor" href="#session-management" aria-label="Permalink to &quot;Session Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Description</th><th>Always available</th></tr></thead><tbody><tr><td><code>/new</code></td><td><code>/clear</code></td><td>Start a fresh session, discarding the current context</td><td>No</td></tr><tr><td><code>/sessions</code></td><td><code>/resume</code></td><td>Browse historical sessions and switch to / restore one</td><td>No</td></tr><tr><td><code>/tasks</code></td><td><code>/task</code></td><td>Browse the background task list</td><td>Yes</td></tr><tr><td><code>/fork</code></td><td>—</td><td>Fork a new session from the current one, preserving the full conversation history; you stay in the current session</td><td>No</td></tr><tr><td><code>/title [&lt;text&gt;]</code></td><td><code>/rename</code></td><td>Without arguments, display the current session title; with an argument, set a new title (max 200 characters)</td><td>Yes</td></tr><tr><td><code>/compact [&lt;instruction&gt;]</code></td><td>—</td><td>Compact the current conversation context to free up token usage; an optional custom instruction can hint to the model what to preserve</td><td>No</td></tr><tr><td><code>/undo [&lt;count&gt;]</code></td><td>—</td><td>Undo recent prompts from the active context. Without a count, opens a selector; with a count, undoes that many prompts. Prompts before the last compaction cannot be undone. Undoing also rolls back the todo list and plan mode state produced by those prompts (code changes are not reverted)</td><td>No</td></tr><tr><td><code>/reload</code></td><td>—</td><td>Reload the current session and apply the latest <code>config.toml</code> settings (providers, models, etc.) and <code>tui.toml</code> UI preferences, without restarting the CLI</td><td>No</td></tr><tr><td><code>/reload-tui</code></td><td>—</td><td>Reload only the <code>tui.toml</code> UI preferences (theme, editor, notifications, etc.) without rebuilding the session</td><td>Yes</td></tr><tr><td><code>/init</code></td><td>—</td><td>Analyze the current codebase and generate <code>AGENTS.md</code></td><td>No</td></tr><tr><td><code>/export-md [&lt;path&gt;]</code></td><td><code>/export</code></td><td>Export the current session as a Markdown file</td><td>No</td></tr><tr><td><code>/export-debug-zip</code></td><td>—</td><td>Export the current session as a debug ZIP archive (same behavior as <a href="./kimi-command.html#kimi-export"><code>kimi export</code></a>)</td><td>No</td></tr><tr><td><code>/copy</code></td><td>—</td><td>Copy the last assistant message to the clipboard</td><td>No</td></tr><tr><td><code>/add-dir [&lt;path&gt;]</code></td><td>—</td><td>Add an extra workspace directory to the current session. Run without a path (or with <code>list</code>) to list configured directories. When adding, choose whether to remember the directory for the project in <code>.kimi-code/local.toml</code></td><td>No</td></tr><tr><td><code>/web</code></td><td>—</td><td>Open the current session in the web UI: pick a running server to connect to, or start a new foreground server after the TUI exits. See <a href="./kimi-command.html#kimi-web"><code>kimi web</code></a></td><td>Yes</td></tr></tbody></table><h2 id="modes-run-control" tabindex="-1">Modes &amp; Run Control <a class="header-anchor" href="#modes-run-control" aria-label="Permalink to &quot;Modes &amp; Run Control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Description</th><th>Always available</th></tr></thead><tbody><tr><td><code>/yolo [on|off]</code></td><td><code>/yes</code></td><td>Toggle YOLO mode. Without arguments, flips the current state; explicitly passing <code>on</code>/<code>off</code> forces the setting. When enabled, skips approval for regular tool calls; Plan mode exit approval is not affected</td><td>Yes</td></tr><tr><td><code>/auto [on|off]</code></td><td>—</td><td>Toggle auto permission mode. When enabled, tool approvals are handled automatically and the Agent will not ask the user questions</td><td>Yes</td></tr><tr><td><code>/plan [on|off]</code></td><td>—</td><td>Toggle Plan mode. Without arguments, flips the current state; explicitly passing <code>on</code>/<code>off</code> forces the setting. Simply toggling does not create an empty plan file</td><td>Yes</td></tr><tr><td><code>/plan clear</code></td><td>—</td><td>Clear the current plan</td><td>No</td></tr><tr><td><code>/swarm on|off</code></td><td>—</td><td>Turn swarm mode on or off without sending a prompt.</td><td>Yes</td></tr><tr><td><code>/swarm &lt;task&gt;</code></td><td>—</td><td>Turn swarm mode on, then send <code>&lt;task&gt;</code> as a normal prompt. If the turn completes normally, swarm mode turns off automatically. In <code>manual</code> permission mode, Kimi Code asks whether to switch to <code>auto</code> or <code>yolo</code> before starting.</td><td>No</td></tr><tr><td><code>/goal [...]</code></td><td>—</td><td>Start or manage an autonomous goal</td><td>See below</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>/yolo</code> skips approval for regular tool calls. Please make sure you understand the potential risks before enabling it. Plan mode exit approval is not bypassed by <code>/yolo</code>; <code>Bash</code> inside Plan mode is still subject to the regular <code>/yolo</code> allow rules.</p></div><h2 id="autonomous-goal" tabindex="-1">Autonomous Goal <a class="header-anchor" href="#autonomous-goal" aria-label="Permalink to &quot;Autonomous Goal&quot;">​</a></h2><p><code>/goal</code> starts or manages goal mode: a persistent objective that Kimi Code works toward across automatically continuing turns. For usage guidance and examples, see <a href="./../guides/goals.html">Goals</a>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> if</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> still</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blocked</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> after</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> turns</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>Action</th><th>Availability</th></tr></thead><tbody><tr><td><code>/goal</code> or <code>/goal status</code></td><td>Display the current goal along with its status, elapsed time, turn count, and token count</td><td>Always available</td></tr><tr><td><code>/goal pause</code></td><td>Pause an active goal and keep it</td><td>Always available</td></tr><tr><td><code>/goal resume</code></td><td>Resume a paused or blocked goal</td><td>Idle only</td></tr><tr><td><code>/goal cancel</code></td><td>Remove the current goal</td><td>Always available</td></tr><tr><td><code>/goal replace &lt;objective&gt;</code></td><td>Replace the saved goal with a new objective</td><td>Idle only</td></tr><tr><td><code>/goal next &lt;objective&gt;</code></td><td>Queue an upcoming goal for this session. If no goal is active, start it immediately. The agent does not see queued goals until the current goal completes</td><td>Always available</td></tr><tr><td><code>/goal next manage</code></td><td>Open the upcoming-goal manager. Use <kbd>↑</kbd> / <kbd>↓</kbd> to browse, <kbd>Space</kbd> to select a goal for moving, selected <kbd>↑</kbd> / <kbd>↓</kbd> to reorder it, <kbd>E</kbd> to edit, <kbd>D</kbd> to delete, and <kbd>Esc</kbd> to cancel. In the edit field, use <kbd>Shift-Enter</kbd> or <kbd>Ctrl-J</kbd> for a new line and <kbd>Enter</kbd> to save</td><td>Always available</td></tr></tbody></table><p>The words <code>status</code>, <code>pause</code>, <code>resume</code>, <code>cancel</code>, <code>replace</code>, and <code>next</code> act as subcommands only when they are the first word after <code>/goal</code>. If your objective needs to start with one of those words, put <code>--</code> before it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cancel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> old</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> note</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> after</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> are</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> published</span></span></code></pre></div><p>If an upcoming goal needs to start with <code>manage</code>, put <code>--</code> after <code>next</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checklist</span></span></code></pre></div><p>In non-interactive prompt mode, only the create forms start goal mode:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/goal Fix the failing checkout test&quot;</span></span></code></pre></div><p>Prompt mode exits with code <code>0</code> when the goal completes, <code>3</code> when it blocks, and <code>6</code> when it pauses. Other <code>/goal</code> subcommands, including <code>next</code>, are TUI controls and are not handled by <code>kimi -p</code>.</p><h2 id="information-status" tabindex="-1">Information &amp; Status <a class="header-anchor" href="#information-status" aria-label="Permalink to &quot;Information &amp; Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Description</th><th>Always available</th></tr></thead><tbody><tr><td><code>/help</code></td><td><code>/h</code>, <code>/?</code></td><td>Show keyboard shortcuts and all available commands</td><td>Yes</td></tr><tr><td><code>/btw [question]</code></td><td>—</td><td>Open a side conversation in a forked sub-Agent without affecting the current main Agent turn; without a question, opens the panel first to wait for input</td><td>Yes</td></tr><tr><td><code>/usage</code></td><td>—</td><td>Show token usage, context consumption, and quota information</td><td>Yes</td></tr><tr><td><code>/status</code></td><td>—</td><td>Show the current session runtime state: version, model, working directory, permission mode, etc.</td><td>Yes</td></tr><tr><td><code>/mcp</code></td><td>—</td><td>List MCP servers and their connection status in the current session</td><td>Yes</td></tr><tr><td><code>/plugins</code></td><td>—</td><td>Open the interactive plugin manager</td><td>Yes</td></tr><tr><td><code>/version</code></td><td>—</td><td>Display the Kimi Code CLI version number</td><td>Yes</td></tr><tr><td><code>/feedback</code></td><td><code>/bug</code></td><td>Submit feedback with optional diagnostic logs and codebase context</td><td>Yes</td></tr><tr><td><code>/team [on|off]</code></td><td>—</td><td>Without arguments, opens the team overview panel (all members&#39; roles, effective models, average scores / score counts). Pass <code>on</code> to enable team mode (making the five management tools visible to the main Agent), or <code>off</code> to disable it. Terminal subagent call cards show &quot;name · role · model · last score&quot;. See <a href="./../guides/team.html">Build your team</a> for details</td><td>Yes</td></tr></tbody></table><h2 id="exit" tabindex="-1">Exit <a class="header-anchor" href="#exit" aria-label="Permalink to &quot;Exit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Description</th><th>Always available</th></tr></thead><tbody><tr><td><code>/exit</code></td><td><code>/quit</code>, <code>/q</code></td><td>Exit Kimi Code CLI</td><td>No</td></tr></tbody></table><h2 id="built-in-skill-commands" tabindex="-1">Built-in skill commands <a class="header-anchor" href="#built-in-skill-commands" aria-label="Permalink to &quot;Built-in skill commands&quot;">​</a></h2><p>Kimi Code CLI ships with a set of built-in Skills that appear directly as <code>/&lt;name&gt;</code> slash commands. Unlike external Skills, they do not require the <code>skill:</code> prefix and are available out of the box.</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/mcp-config</code></td><td>Configure MCP servers and handle MCP OAuth login. See <a href="./../customization/mcp.html">MCP</a></td></tr><tr><td><code>/custom-theme [&lt;text&gt;]</code></td><td>Create or edit a custom TUI color theme. See <a href="./../customization/themes.html">Themes</a></td></tr><tr><td><code>/update-config</code></td><td>Inspect or edit <code>config.toml</code> (model, provider, permission, hooks) and <code>tui.toml</code> (theme, editor, notifications, auto-update)</td></tr><tr><td><code>/check-kimi-code-docs</code></td><td>Answer Kimi Code product questions (CLI usage, configuration, membership, error codes) against the official docs</td></tr><tr><td><code>/import-from-cc-codex</code></td><td>Import Claude Code and Codex instructions, skills, and MCP settings into Kimi Code</td></tr><tr><td><code>/sub-skill</code></td><td>Discover and reorganize the local skill inventory into hierarchical sub-skill bundles. Includes <code>/sub-skill.review</code> (read-only proposal) and <code>/sub-skill.consolidate</code> (apply the reorganization)</td></tr></tbody></table><p>All built-in Skill commands are only available in the idle state.</p><h2 id="skill-dynamic-commands" tabindex="-1">Skill Dynamic Commands <a class="header-anchor" href="#skill-dynamic-commands" aria-label="Permalink to &quot;Skill Dynamic Commands&quot;">​</a></h2><p>Activated external Skills are automatically registered as slash commands. Ordinary external Skills use the <code>skill:</code> namespace prefix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/skill:&lt;name&gt; [extra text]</span></span></code></pre></div><p>For example, <code>/skill:code-style</code> loads the Skill named <code>code-style</code> and sends it to the Agent; any text appended after the command is concatenated to the Skill prompt.</p><p>External sub-skills appear directly in the slash command panel with dotted names:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/&lt;parent-skill&gt;.&lt;sub-skill&gt; [extra text]</span></span></code></pre></div><p>For example, a child Skill named <code>review</code> inside a parent Skill named <code>code-style</code> is shown as <code>/code-style.review</code>. The dotted command name is derived from the hierarchy; the child <code>SKILL.md</code> can keep its local <code>name</code>.</p><p>For convenience, external Skill commands also support a shorthand form that omits the <code>skill:</code> prefix — <code>/&lt;name&gt;</code> — as long as the name is not taken by a system slash command. That is, <code>/code-style</code> falls back to matching <code>/skill:code-style</code>.</p><p>Built-in Skills shipped with Kimi Code CLI appear directly as <code>/&lt;name&gt;</code> in the slash command panel. For example, <code>/mcp-config</code> helps configure MCP servers and handle MCP OAuth login, and <code>/custom-theme [extra text]</code> invokes the custom-theme workflow to create or edit a TUI theme.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>All Skill commands are only available in the idle state. <code>flow</code>-type Skills are also exposed via <code>/skill:&lt;name&gt;</code> — there is no separate <code>/flow:</code> namespace.</p></div><p>For installing and authoring Skills, see <a href="./../customization/skills.html">Agent Skills</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./keyboard.html">Keyboard Shortcuts</a> — Quick reference for TUI keyboard operations</li><li><a href="./../guides/team.html">Build your team</a> — A user-facing guide on building and managing an AI coding team from scratch</li><li><a href="./tools.html">Built-in Tools</a> — Complete reference for tools the Agent can call</li></ul>',44)])])}const u=e(s,[["render",i]]);export{m as __pageData,u as default};
